{"implementation": "import copy
def solve(case):
    if 'text' not in case or 'passes' not in case or 'max_rounds' not in case:
        raise ValueError('Missing required field')
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    if not isinstance(text, str) or not isinstance(passes, list) or not isinstance(max_rounds, int):
        raise ValueError('Invalid field types')
    current = text
    applications = []
    changed = False
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            if p['old'] in current:
                current = current.replace(p['old'], p['new'], 1)
                applications.append(p['name'])
                changed = True
        if not changed:
            break
    return {'applications': applications, 'fixed_point': not changed, 'text': current}
"}
